def analyze(i):
    i=np.array(i); h,w=i.shape
    cnt=Counter(int(x) for x in i.flatten())
    bg=cnt.most_common(1)[0][0]
    mark=[v for v in cnt if v!=bg][0]
    walls=(i==mark)
    visited=np.zeros((h,w),bool); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if not walls[r,c] and not visited[r,c]: visited[r,c]=True;q.append((r,c))
    for r in (0,h-1):
        for c in range(w):
            if not walls[r,c] and not visited[r,c]: visited[r,c]=True;q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and not walls[nr,nc] and not visited[nr,nc]:
                visited[nr,nc]=True;q.append((nr,nc))
    pred=i.copy()
    enc = (~visited)&(~walls)
    pred[enc]=2
    return pred
